      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00547",
        "explanation": "Adapts the plan to caregiver burden by distributing monitoring and phone responsibility.",
        "quote": "最好再找一位家人轮班接电话和照看"
      }
    ]
  },
  "dimension_ratings": {
    "actionability_responsibility_chain": "excellent",
